def _normalise_tracking_uri(uri: Optional[str]) -> Optional[str]:
    if not uri:
        return None
    lowered = uri.lower()
    if lowered.startswith(("http://", "https://", "file://")):
        return uri
    return os.path.abspath(uri)


def _proxy_url(port: int, suffix: str, absolute: bool = True) -> str:
    rel = f"/proxy/absolute/{port}/{suffix}/"
    if not absolute:
        return rel
    root = (
        os.environ.get("JUPYTERHUB_ROOT_URL")
        or os.environ.get("NB_URL")
        or os.environ.get("NB_HOST")
        or os.environ.get("AIM_UI_ORIGIN")
        or "http://127.0.0.1:8888"
    )
    root = root.rstrip("/")
    return f"{root}{rel}"


def start_mlflow_ui(
    tracking_uri: Optional[str],
    port: int,
    suffix: str,
    base_url: Optional[str] = None,
) -> Optional[str]:
    cli_path = shutil.which("mlflow")
    if cli_path is None:
        return None
    backend_uri = _normalise_tracking_uri(tracking_uri or get_tracking_uri())
    subprocess.run(
        ["bash", "-lc", f"pkill -f 'mlflow ui .*{port}' || true"],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    prefix = f"/proxy/absolute/{port}/{suffix}"
    command = [
        cli_path,
        "ui",
        "--host",
        "127.0.0.1",
        "--port",
        str(port),
        "--static-prefix",
        prefix,
    ]
    if backend_uri:
        command.extend(["--backend-store-uri", backend_uri])
    proc = subprocess.Popen(
        command,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
    )

    def port_open(p: int) -> bool:
        sock = socket.socket()
        sock.settimeout(0.2)
        try:
            sock.connect(("127.0.0.1", p))
            sock.close()
            return True
        except OSError:
            return False

    for _ in range(60):
        if port_open(port):
            break
        time.sleep(0.5)

    if not port_open(port):
        if proc.stdout:
            lines = proc.stdout.readlines()
            print("MLflow UI did not start. Logs:\n" + "".join(lines[-200:]))
        return None

    rel_url = _proxy_url(port, suffix, absolute=False)
    abs_url_default = _proxy_url(port, suffix, absolute=True)
    abs_url = abs_url_default
    if base_url:
        abs_url = f"{base_url.rstrip('/')}{rel_url}"

    if "ipykernel" in sys.modules:
        try:
            from IPython.display import HTML, display

            display(
                HTML(
                    f"""
                    <div id="mlflow-link"></div>
                    <script>
                    (function() {{
                      var rel = {rel_url!r};
                      var abs = rel;
                      try {{
                        abs = new URL(rel, window.location.origin).href;
                      }} catch (e) {{}}
                      var a = document.createElement('a');
                      a.href = abs;
                      a.target = "_blank";
                      a.textContent = "Open MLflow UI";
                      var c = document.getElementById('mlflow-link');
                      if (c) c.appendChild(a);
                    }})();
                    </script>
                    """
                )
            )
        except Exception:
            pass

    print(f"MLflow UI (relative): {rel_url}")
    print("(absolute)", abs_url)
    if abs_url_default != abs_url:
        print("(fallback absolute)", abs_url_default)
    return abs_url


