class DatasetMixer:
    def __init__(self, config: TrainingConfig) -> None:
        self.config = config
        self.last_mix: Optional[List[Dict[str, Any]]] = None
        self._info_cache: Dict[Tuple[str, Optional[str]], Dict[str, Any]] = {}

    @staticmethod
    def _strip_brackets(text: str) -> str:
        return re.sub(r"\[[^\]]*\]", "", text)

    @staticmethod
    def _nested_get(example: Dict[str, Any], path: str) -> Any:
        cursor: Any = example
        for part in path.split("."):
            cursor = cursor[part]
        return cursor

    def _resolve_config_name(self, dataset_id: str, config_name: Optional[str]) -> Optional[str]:
        if config_name is not None:
            return config_name
        configs = get_dataset_config_names(dataset_id, token=self.config.hf_token)
        if not configs:
            return None
        if len(configs) == 1:
            return configs[0]
        raise ValueError(f"Dataset {dataset_id} has multiple configs; specify one explicitly")

    def _load_dataset_info(self, dataset_id: str, config_name: Optional[str]) -> Dict[str, Any]:
        resolved_config = self._resolve_config_name(dataset_id, config_name)
        key = (dataset_id, resolved_config)
        if key in self._info_cache:
            return self._info_cache[key]

        builder = load_dataset_builder(
            dataset_id,
            resolved_config,
            token=self.config.hf_token,
        )
        info = {
            "splits": {
                name: {"num_examples": split.num_examples}
                for name, split in builder.info.splits.items()
            }
        }
        self._info_cache[key] = info
        return info

    def source_weight(self, source: DatasetSource) -> int:
        if source.weight is not None:
            return source.weight
        info = self._load_dataset_info(source.dataset_id, source.config_name)
        splits = info.get("splits", {})
        if source.split not in splits:
            raise ValueError(f"split {source.split} not available for {source.dataset_id}")
        return int(splits[source.split]["num_examples"])

    def describe_sources(self, sources: List[DatasetSource]) -> List[Dict[str, Any]]:
        try:
            entries: List[Dict[str, Any]] = []
            total = 0.0
            for source in sources:
                weight = float(self.source_weight(source))
                total += weight
                entries.append(
                    {
                        "dataset": source.dataset_id,
                        "config": source.config_name or "-",
                        "split": source.split,
                        "weight": weight,
                    }
                )
            for entry in entries:
                entry["probability"] = (entry["weight"] / total) if total > 0 else 0.0
            return entries
        except Exception as exc:
            print(f"[warn] failed to fetch dataset sizes: {exc}")
            return [
                {
                    "dataset": src.dataset_id,
                    "config": src.config_name or "-",
                    "split": src.split,
                    "weight": float('nan'),
                    "probability": float('nan'),
                }
                for src in sources
            ]

    def prepare_source(self, source: DatasetSource, seed: int) -> Any:
        # Restrict LibriSpeech 'clean' to the exact split to avoid pulling other splits
        common_kwargs = dict(streaming=False, token=self.config.hf_token, download_config=DownloadConfig(max_retries=10), verification_mode="no_checks", keep_in_memory=True)
        if source.dataset_id == "librispeech_asr" and (source.config_name or "") == "clean":
            if source.split in ("train.360", "train.100", "validation", "test"):
                dataset = load_dataset(
                    source.dataset_id,
                    source.config_name,
                    data_files={source.split: f"clean/{source.split}/*.parquet"},
                    split=source.split,
                    **common_kwargs,
                )
            else:
                dataset = load_dataset(
                    source.dataset_id,
                    source.config_name,
                    split=source.split,
                    **common_kwargs,
                )
        else:
            dataset = load_dataset(
                source.dataset_id,
                source.config_name,
                split=source.split,
                **common_kwargs,
            )
        # We only need text; drop heavy columns if present
        try:
            drop_cols = [c for c in dataset.column_names if c not in ("text", "transcript", "transcript_c")]
            if drop_cols:
                dataset = dataset.remove_columns(drop_cols)
        except Exception:
            pass

        def project(example: Dict[str, Any]) -> Dict[str, Any]:
            # if source.dataset_id == "euclaise/writingprompts":
            #     prompt = self._strip_brackets(example["prompt"])
            #     story = self._strip_brackets(example["story"])
            #     return {"text": (prompt.strip() + "\n\n" + story.strip()).strip()}
            # if source.dataset_id == "krisha05/story-generation-dataset":
            #     instruction = example["instruction"].replace("### Instruction:", "").replace("### Response:", "").strip()
            #     output = example["output"].replace("### Instruction:", "").replace("### Response:", "").strip()
            #     return {"text": (instruction + "\n\n" + output).strip()}
            # if source.dataset_id == "Dans-DiscountModels/RUCAIBox-Story-Generation-Alpaca":
            #     instruction = example.get("instruction", "").strip()
            #     inp = example.get("input", "").strip()
            #     output = example.get("output", "").strip()
            #     combined_prompt = f"{instruction}\n\n{inp}".strip()
            #     return {"text": (combined_prompt + "\n\n" + output).strip()}
            # raise ValueError(f"Unsupported dataset {source.dataset_id}")

            # Plain instruction format, no special tokens:
            if source.dataset_id == "librispeech_asr":
                raw_text = example.get("text", "")
            elif source.dataset_id == "istupakov/russian_librispeech":
                raw_text = example.get("text", "")
            elif source.dataset_id == "amaai-lab/DisfluencySpeech":
                # Use cleaned transcript as reference
                raw_text = example.get("transcript_c", example.get("transcript", ""))
            else:
                raw_text = example.get("text", "")

            txt = str(raw_text or "").strip()
            if not txt:
                return {"text": ""}

            instruction = "Transcribe the following dictated text and change it according to instructions:\n"
            prompt = f"{instruction}{txt}"
            # Separator blank line between prompt and target. Target is the same text.
            return {"text": (prompt + "\n\n" + txt)}

        dataset = dataset.map(project, remove_columns=dataset.column_names, load_from_cache_file=False)
        dataset = dataset.filter(lambda example: isinstance(example["text"], str) and example["text"].strip() != "")
        dataset = dataset.shuffle(seed=seed)
        return dataset

    def build(self, sources: List[DatasetSource], seed: int) -> Any:
        datasets = []
        weights = []
        entries: List[Dict[str, Any]] = []
        for index, source in enumerate(sources):
            dataset = self.prepare_source(source, seed + index)
            weight = float(self.source_weight(source))
            datasets.append(dataset)
            weights.append(weight)
            entries.append(
                {
                    "dataset": source.dataset_id,
                    "config": source.config_name or "-",
                    "split": source.split,
                    "weight": weight,
                }
            )
        total = float(sum(weights))
        probabilities = [w / total for w in weights] if total > 0 else [0.0 for _ in weights]
        for entry, prob in zip(entries, probabilities):
            entry["probability"] = prob
        self.last_mix = entries
        mixed = interleave_datasets(datasets, probabilities=probabilities, seed=seed, stopping_strategy="first_exhausted")
        return mixed


class StreamingTextDataset(IterableDataset):
    def __init__(self, dataset: Any, tokenizer: AutoTokenizer, config: TrainingConfig) -> None:
        super().__init__()
        self.dataset = dataset
        self.tokenizer = tokenizer
        self.config = config

    def preprocess(self, sample: Dict[str, Any]) -> Dict[str, torch.Tensor]:
        # Split once on a blank line between prompt and target.
        # Our DatasetMixer formats examples as: PROMPT + "\n\n" + OUTPUT.
        text: str = sample["text"]
        sep = "\n\n"
        if sep in text:
            cut = text.find(sep) + len(sep)
            prompt_text = text[:cut]
            target_text = text[cut:]
        else:
            prompt_text = ""
            target_text = text

        tok = self.tokenizer
        # Tokenize *without* adding special tokens; concatenate manually
        enc_prompt = tok(prompt_text, return_tensors="pt", add_special_tokens=False)
        enc_target = tok(target_text, return_tensors="pt", add_special_tokens=False)
        prompt_ids = enc_prompt.input_ids[0]
        target_ids = enc_target.input_ids[0]

        max_len = self.config.max_length
        input_ids = torch.cat([prompt_ids, target_ids], dim=0)
        if input_ids.size(0) > max_len:
            # If we have to truncate, prefer to keep the tail of the target
            # while preserving the full prompt when possible.
            keep = max_len
            if prompt_ids.size(0) >= keep:
                input_ids = prompt_ids[-keep:]
                prompt_kept = input_ids.size(0)
            else:
                prompt_kept = prompt_ids.size(0)
                input_ids = torch.cat([prompt_ids, target_ids[: keep - prompt_kept]], dim=0)
        else:
            prompt_kept = prompt_ids.size(0)

        labels = torch.full_like(input_ids, -100)
        if input_ids.size(0) > prompt_kept:
            labels[prompt_kept:] = input_ids[prompt_kept:]
        return {"input_ids": input_ids, "labels": labels}

    def __iter__(self) -> Iterable[Dict[str, torch.Tensor]]:
        worker = get_worker_info()
        if worker is None:
            iterator = iter(self.dataset)
        else:
            try:
                shard = self.dataset.shard(num_shards=worker.num_workers, index=worker.id, contiguous=False)
            except Exception:
                shard = self.dataset
            iterator = iter(shard)
        for sample in iterator:
            yield self.preprocess(sample)


def collate_batch(batch: List[Dict[str, torch.Tensor]], pad_token: int) -> Optional[Dict[str, torch.Tensor]]:
    if not batch:
        return None
    input_ids = pad_sequence([item["input_ids"] for item in batch], batch_first=True, padding_value=pad_token).long()
    labels = pad_sequence([item["labels"] for item in batch], batch_first=True, padding_value=-100).long()
    attention_mask = (input_ids != pad_token).long()
    return {"input_ids": input_ids, "labels": labels, "attention_mask": attention_mask}


def compute_token_accuracy(logits: torch.Tensor, labels: torch.Tensor) -> Tuple[int, int]:
    preds = logits.argmax(dim=-1)
    mask = labels != -100
    correct = int((preds[mask] == labels[mask]).sum().item())
    total = int(mask.sum().item())
    return correct, total


class CheckpointManager:
    def __init__(self, root: str) -> None:
        self.root = root
        os.makedirs(self.root, exist_ok=True)

    def path(self) -> str:
        return os.path.join(self.root, "lora_checkpoint.pt")

    def load(self, device: torch.device) -> Optional[Dict[str, Any]]:
        path = self.path()
        if not os.path.exists(path):
            return None
        return torch.load(path, map_location=device)

    def save(self, payload: Dict[str, Any]) -> None:
        torch.save(payload, self.path())


class MLflowLogger:
    def __init__(self, config: TrainingConfig) -> None:
        self.enabled = config.use_mlflow
        self.active = False
        self.ui_url: Optional[str] = None
        if not self.enabled:
            return
        if config.mlflow_tracking_uri:
            set_tracking_uri(config.mlflow_tracking_uri)
        set_experiment(config.mlflow_experiment)
        tags = {tag: "true" for tag in config.mlflow_tags}
        self.run = start_run(run_name=f"{config.mlflow_run_name}-{datetime.now().strftime('%Y%m%d_%H%M%S')}", tags=tags)
        self.active = True
        log_params({k: v for k, v in asdict(config).items() if isinstance(v, (int, float, str, bool))})
        if config.mlflow_ui_autostart:
            self.ui_url = start_mlflow_ui(
                tracking_uri=config.mlflow_tracking_uri or get_tracking_uri(),
                port=config.mlflow_ui_port,
                suffix=config.mlflow_ui_suffix,
                base_url=config.mlflow_ui_base_url,
            )
            if self.ui_url:
                self.log_text("mlflow_ui_url", self.ui_url)

    def log_scalar(self, key: str, value: float, step: int) -> None:
        if not self.active:
            return
        log_metric(key, value, step=step)

    def log_text(self, key: str, value: str) -> None:
        if not self.active:
            return
        log_text(value, key)

    def close(self) -> None:
        if not self.active:
            return
        end_run()
        self.active = False


def evaluate(
    model: nn.Module,
    loader: DataLoader,
    device: torch.device,
    dtype: torch.dtype,
    max_batches: int,
    tokenizer: AutoTokenizer,
    preview_examples: int = 3,
    preview_prompt_tokens: int = 128,
    preview_max_new_tokens: int = 128,
) -> Tuple[float, float, List[Dict[str, str]]]:
    model.eval()
    total_loss = 0.0
    total_tokens = 0
    total_correct = 0.0
    batches = 0
    examples: List[Dict[str, str]] = []
    with torch.no_grad():
        for batch in loader:
            if batch is None:
                continue
            input_ids = batch["input_ids"].to(device=device, dtype=torch.long)
            labels = batch["labels"].to(device=device, dtype=torch.long)
            attention_mask = batch["attention_mask"].to(device=device, dtype=torch.long)
            with autocast(device_type=device.type, dtype=dtype, enabled=True):
                outputs = model(input_ids=input_ids, attention_mask=attention_mask, labels=labels)
            loss = outputs.loss
            correct, tokens = compute_token_accuracy(outputs.logits.detach(), labels.detach())
            total_loss += float(loss.item()) * tokens
            total_correct += correct
            total_tokens += tokens
            if len(examples) < preview_examples and input_ids.size(0) > 0:
                sample_ids = input_ids[0]
                label_row = labels[0]
                # prompt length = number of leading -100 in labels
                prompt_mask = (label_row == -100).to(torch.int)
                # find first index where labels become supervised
                if prompt_mask.sum() > 0:
                    prompt_len = int(prompt_mask.argmin().item()) if (prompt_mask == 0).any() else sample_ids.size(0)
                else:
                    prompt_len = min(preview_prompt_tokens, sample_ids.size(0))
                prompt_len = max(0, min(prompt_len, sample_ids.size(0)))

                prompt_ids = sample_ids[:prompt_len]
                target_ids = sample_ids[prompt_len:]
                prompt_text = tokenizer.decode(prompt_ids, skip_special_tokens=True)
                target_text = tokenizer.decode(target_ids, skip_special_tokens=True)

                prompt_batch = prompt_ids.unsqueeze(0).to(device=device, dtype=torch.long)
                attn = torch.ones_like(prompt_batch, device=device)
                with autocast(device_type=device.type, dtype=dtype, enabled=True):
                    generated_ids = model.generate(
                        input_ids=prompt_batch,
                        attention_mask=attn,
                        max_new_tokens=preview_max_new_tokens,
                        do_sample=True,
                        temperature=0.7,
                        top_p=0.95,
                        top_k=50,
                        no_repeat_ngram_size=4,
                        repetition_penalty=1.08,
                        eos_token_id=tokenizer.eos_token_id,
                        pad_token_id=tokenizer.pad_token_id,
                        use_cache=True,
                    )
                generated_text = tokenizer.decode(generated_ids[0][prompt_batch.size(1) :], skip_special_tokens=True)
                examples.append(
                    {
                        "prompt": prompt_text,
                        "target": target_text,
                        "generated": generated_text,
                    }
                )
            batches += 1
            if batches >= max_batches:
                break
    model.train()
    avg_loss = total_loss / max(1, total_tokens)
    token_acc = (total_correct / max(1, total_tokens)) if total_tokens > 0 else 0.0
    return avg_loss, token_acc, examples


def build_scheduler(optimizer: torch.optim.Optimizer, warmup_steps: int) -> LambdaLR:
    def lr_lambda(step: int) -> float:
        if warmup_steps <= 0:
            return 1.0
        if step < warmup_steps:
            return float(step + 1) / float(warmup_steps)
        return 1.0

    return LambdaLR(optimizer, lr_lambda=lr_lambda)


def load_model_and_tokenizer(config: TrainingConfig, device: torch.device, dtype: torch.dtype) -> Tuple[AutoTokenizer, nn.Module]:
    tokenizer = AutoTokenizer.from_pretrained(config.llm_model, padding_side="left", token=config.hf_token, trust_remote_code=True)
    # do not add any new special tokens; use EOS for padding
    if tokenizer.pad_token_id is None:
        tokenizer.pad_token = tokenizer.eos_token
    # make sure model respects these ids
    # (no vocabulary resize due to added tokens)
    text_config = AutoConfig.from_pretrained(config.llm_model, trust_remote_code=True, token=config.hf_token)
    if config.quantize_4bit:
        bnb_config = BitsAndBytesConfig(
            load_in_4bit=True,
            bnb_4bit_compute_dtype=getattr(torch, config.bnb_compute_dtype),
            bnb_4bit_use_double_quant=True,
            bnb_4bit_quant_type="nf4",
        )
        llm = AutoModelForCausalLM.from_pretrained(
            config.llm_model,
            config=text_config,
            device_map="auto",
            quantization_config=bnb_config,
            torch_dtype=getattr(torch, config.bnb_compute_dtype),
            token=config.hf_token,
            trust_remote_code=True,
        )
        llm.gradient_checkpointing_enable()
        llm = prepare_model_for_kbit_training(llm)
        llm.config.use_cache = False
    else:
        llm = AutoModelForCausalLM.from_pretrained(
            config.llm_model,
            config=text_config,
            torch_dtype=dtype,
            device_map={"": device},
            token=config.hf_token,
            trust_remote_code=True,
        )
    llm.config.pad_token_id = tokenizer.pad_token_id
    llm.config.eos_token_id = tokenizer.eos_token_id
    llm.resize_token_embeddings(len(tokenizer))
    lora_cfg = LoraConfig(
        r=64,
        lora_alpha=128,
        lora_dropout=0.1,
        target_modules=["k_proj", "v_proj", "o_proj", "gate_proj", "up_proj"],
        task_type=TaskType.CAUSAL_LM,
        init_lora_weights=True,
    )
    llm = get_peft_model(llm, lora_cfg)
    llm.config.attn_implementation = "eager"
    return tokenizer, llm


class Trainer:
    def __init__(self, config: TrainingConfig) -> None:
        self.config = config
        if not torch.cuda.is_available():
            raise RuntimeError("CUDA is required for LoRA fine-tuning in this script.")
        self.device = torch.device("cuda")
        self.dtype = torch.bfloat16 if torch.cuda.is_bf16_supported() else torch.float16
        set_seed(config.seed)
        self.tokenizer, self.model = load_model_and_tokenizer(config, self.device, self.dtype)
        self.mixer = DatasetMixer(config)
        self.checkpoints = CheckpointManager(config.output_dir)
        self.train_mix_info = self.mixer.describe_sources(self.config.train_sources)
        self.eval_mix_info = self.mixer.describe_sources(self.config.eval_sources)
        self.train_total_samples = sum(item["weight"] for item in self.train_mix_info)
        self.eval_total_samples = sum(item["weight"] for item in self.eval_mix_info)
        self.print_mix_report("train", self.train_mix_info)
        self.print_mix_report("eval", self.eval_mix_info)
        self.logger: MLflowLogger | None = None

    def start_logging(self) -> None:
        self.logger = MLflowLogger(self.config)
        if self.logger.active:
            self.logger.log_text(
                "dataset_mixture",
                json.dumps({"train": self.train_mix_info, "eval": self.eval_mix_info}, ensure_ascii=False, indent=2),
            )

    @staticmethod
    def _preview(text: str, limit: int = 160) -> str:
        clean = text.replace("\n", " ").strip()
        return clean if len(clean) <= limit else clean[: limit - 3] + "..."

    def print_mix_report(self, label: str, mix_info: List[Dict[str, Any]]) -> None:
        finite_weights = [item["weight"] for item in mix_info if math.isfinite(item["weight"])]
        total = sum(finite_weights) if finite_weights else float("nan")
        if math.isfinite(total):
            print(f"[mixture:{label}] estimated total≈{int(total)} samples")
        else:
            print(f"[mixture:{label}] total samples≈unknown (dataset size lookup failed)")
        for item in mix_info:
            weight = item.get("weight", float("nan"))
            prob = item.get("probability", float("nan"))
            weight_str = f"{int(weight)}" if math.isfinite(weight) else "unknown"
            percent = prob * 100.0 if math.isfinite(prob) else float("nan")
            config_name = item["config"] if item["config"] else "-"
            if math.isfinite(percent):
                percent_str = f"{percent:.2f}%"
            else:
                percent_str = "unknown"
            print(f"  - {item['dataset']}[{config_name}/{item['split']}] weight≈{weight_str} ({percent_str})")

    def dataloader(self, sources: List[DatasetSource], batch_size: int, workers: int) -> DataLoader:
        dataset = self.mixer.build(sources, self.config.seed)
        iterable = StreamingTextDataset(dataset, self.tokenizer, self.config)
        kwargs: Dict[str, Any] = {
            "batch_size": batch_size,
            "shuffle": False,
            "num_workers": min(workers, 1),
            "collate_fn": lambda batch: collate_batch(batch, self.tokenizer.pad_token_id),
            "pin_memory": True,
        }
        if workers > 0:
            kwargs["prefetch_factor"] = self.config.prefetch_factor
        return DataLoader(iterable, **kwargs)

    def optimizer(self) -> torch.optim.Optimizer:
        params = [p for p in self.model.parameters() if p.requires_grad]
        return torch.optim.AdamW(params, lr=self.config.lr, betas=(0.9, 0.95), weight_decay=0.0)

    def train(self) -> None:
        train_loader = self.dataloader(self.config.train_sources, self.config.batch_size, self.config.train_workers)
        optimizer = self.optimizer()
        scheduler = build_scheduler(optimizer, self.config.warmup_steps)
        scaler = GradScaler(enabled=(self.device.type == "cuda"))
        start_step = 0
        global_step = 0
        samples_seen = 0
        expected_total = self.train_total_samples
        print(
            f"[start] total_expected_samples≈{int(expected_total)} | epochs={self.config.epochs} | batch_size={self.config.batch_size}"
        )
        if self.config.resume:
            checkpoint = self.checkpoints.load(self.device)
            if checkpoint:
                set_peft_model_state_dict(self.model, checkpoint["lora"])  # LoRA always safe to load

                # Optimizer/Scheduler resume can fail if the optimizer type changed (e.g., Lion -> AdamW)
                saved_opt_class = checkpoint.get("optimizer_class", "<unknown>")
                current_opt_class = optimizer.__class__.__name__
                optimizer_loaded = False

                if "optimizer" in checkpoint and saved_opt_class == current_opt_class:
                    try:
                        optimizer.load_state_dict(checkpoint["optimizer"])  # same optimizer type
                        optimizer_loaded = True
                    except Exception as e:
                        print(f"[resume] optimizer state incompatible ({e}); starting with fresh optimizer")
                else:
                    if "optimizer" in checkpoint:
                        print(f"[resume] optimizer type changed: saved={saved_opt_class} now={current_opt_class}; starting fresh optimizer")

                if optimizer_loaded and "scheduler" in checkpoint:
                    try:
                        scheduler.load_state_dict(checkpoint["scheduler"])  # only if optimizer loaded
                    except Exception as e:
                        print(f"[resume] scheduler state incompatible ({e}); using fresh scheduler")

                if "scaler" in checkpoint:
                    try:
                        scaler.load_state_dict(checkpoint["scaler"])  # safe even if optimizer fresh
                    except Exception as e:
                        print(f"[resume] scaler state incompatible ({e}); using fresh scaler")

                global_step = int(checkpoint.get("global_step", 0))
                start_step = global_step
                samples_seen = int(checkpoint.get("samples_seen", 0))
                remaining = max(0.0, expected_total - samples_seen)
                progress = (samples_seen / expected_total) * 100.0 if expected_total > 0 else 0.0
                resume_msg = (
                    f"[resume] step={global_step} samples_seen={samples_seen} (~{progress:.2f}% of epoch) "
                    f"remaining≈{int(remaining)}"
                )
                print(resume_msg)
                self.logger.log_text("resume_info", resume_msg)
        self.model.train()
        for epoch in range(self.config.epochs):
            for step, batch in enumerate(train_loader):
                if batch is None:
                    continue
                input_ids = batch["input_ids"].to(device=self.device, dtype=torch.long)
                labels = batch["labels"].to(device=self.device, dtype=torch.long)
                attention_mask = batch["attention_mask"].to(device=self.device, dtype=torch.long)
                batch_size = input_ids.size(0)
                samples_seen += batch_size
                with autocast(device_type=self.device.type, dtype=self.dtype, enabled=True):
                    outputs = self.model(input_ids=input_ids, attention_mask=attention_mask, labels=labels)
                    loss = outputs.loss / self.config.gradient_accumulation_steps
                if not torch.isfinite(loss):
                    print(
                        f"[nan-loss] epoch={epoch} step={global_step} loss={loss.item()} "
                        f"prompt={self._preview(self.tokenizer.decode(input_ids[0][: min(128, input_ids.size(1))], skip_special_tokens=True))}"
                    )
                    optimizer.zero_grad(set_to_none=True)
                    continue
                scaler.scale(loss).backward()
                should_step = (step + 1) % self.config.gradient_accumulation_steps == 0
                if should_step:
                    scaler.unscale_(optimizer)
                    grad_norm = torch.nn.utils.clip_grad_norm_(self.model.parameters(), self.config.clip_threshold)
                    if not torch.isfinite(grad_norm):
                        print(f"[nan-grad] epoch={epoch} step={global_step} grad_norm={grad_norm}")
                        optimizer.zero_grad(set_to_none=True)
                        continue
                    if scaler.is_enabled():
                        scaler.step(optimizer)
                        scaler.update()
                    else:
                        optimizer.step()
                    optimizer.zero_grad(set_to_none=True)
                    scheduler.step()
                    global_step += 1
                    if global_step % self.config.log_every_n_steps == 0:
                        step_loss = float(loss.item() * self.config.gradient_accumulation_steps)
                        current_lr = optimizer.param_groups[0]["lr"]
                        grad_value = float(grad_norm.item() if hasattr(grad_norm, "item") else grad_norm)
                        ppl = float(math.exp(min(50.0, step_loss)))
                        train_correct, train_tokens = compute_token_accuracy(outputs.logits.detach(), labels.detach())
                        train_acc = (train_correct / max(1, train_tokens)) * 100.0
                        progress = (samples_seen / expected_total) * 100.0 if expected_total > 0 else 0.0
                        remaining = max(0.0, expected_total - samples_seen)
                        print(
                            f"[train] epoch={epoch} step={global_step} loss={step_loss:.4f} "
                            f"ppl={ppl:.2f} lr={current_lr:.6f} grad_norm={grad_value:.2f} acc={train_acc:.2f}% "
                            f"samples={samples_seen}/{int(expected_total)} (~{progress:.2f}% ) remain≈{int(remaining)}"
                        )
                        if self.logger and self.logger.active:
                            self.logger.log_scalar("train/loss", step_loss, global_step)
                            self.logger.log_scalar("train/perplexity", ppl, global_step)
                            self.logger.log_scalar("train/lr", float(current_lr), global_step)
                            self.logger.log_scalar("train/grad_norm", grad_value, global_step)
                            self.logger.log_scalar("train/token_acc", train_acc, global_step)
                            self.logger.log_scalar("train/progress_pct", progress, global_step)
                    if global_step % self.config.val_every_n_steps == 0:
                        val_loader = self.dataloader(self.config.eval_sources, self.config.batch_size, self.config.eval_workers)
                        val_loss, val_acc, val_examples = evaluate(
                            self.model,
                            val_loader,
                            self.device,
                            self.dtype,
                            self.config.val_batches,
                            self.tokenizer,
                        )
                        val_ppl = float(math.exp(min(50.0, val_loss)))
                        acc_percent = float(val_acc * 100.0)
                        print(
                            f"[val] step={global_step} loss={val_loss:.4f} ppl={val_ppl:.2f} token_acc={acc_percent:.2f}%"
                        )
                        if self.logger and self.logger.active:
                            self.logger.log_scalar("val/loss", val_loss, global_step)
                            self.logger.log_scalar("val/perplexity", val_ppl, global_step)
                            self.logger.log_scalar("val/token_acc", acc_percent, global_step)
                        if val_examples:
                            preview_payload = json.dumps(val_examples, ensure_ascii=False, indent=2)
                            if self.logger and self.logger.active:
                                self.logger.log_text("val/examples", preview_payload)
                            for idx, example in enumerate(val_examples, 1):
                                print(
                                    f"[val-example {idx}] prompt: {self._preview(example['prompt'])} | "
                                    f"target: {self._preview(example['target'])} | generated: {self._preview(example['generated'])}"
                                )
                        self.save_checkpoint(optimizer, scheduler, scaler, global_step, samples_seen)
        self.save_checkpoint(optimizer, scheduler, scaler, global_step, samples_seen)
        if self.logger and self.logger.active:
            self.logger.close()

    def save_checkpoint(
        self,
        optimizer: torch.optim.Optimizer,
        scheduler: LambdaLR,
        scaler: GradScaler,
        global_step: int,
        samples_seen: int,
    ) -> None:
        payload = {
            "global_step": global_step,
            "optimizer_class": optimizer.__class__.__name__,
            "lora": get_peft_model_state_dict(self.model),
            "optimizer": optimizer.state_dict(),
            "scheduler": scheduler.state_dict(),
            "scaler": scaler.state_dict(),
            "config": asdict(self.config),
            "timestamp": datetime.utcnow().isoformat(),
            "samples_seen": samples_seen,
        }
        self.checkpoints.save(payload)
        print(f"[checkpoint] saved step={global_step} -> {self.checkpoints.path()}")
        if self.logger and self.logger.active:
            self.logger.log_text("checkpoint", f"step={global_step} path={self.checkpoints.path()}")


def prefetch_all_datasets(config: TrainingConfig) -> None:
    seen = set()
    sources = list(config.train_sources) + list(config.eval_sources)
    print("[prefetch] starting prefetch of configured datasets (non-streaming)")
    for src in sources:
        key = (src.dataset_id, src.config_name, src.split)
        if key in seen:
            continue
        seen.add(key)
        label = f"{src.dataset_id}[{src.config_name or '-'}:{src.split}]"
        print(f"[prefetch] {label} ...")
        try:
            # Constrain LibriSpeech 'clean' to the exact split using data_files with matching split key.
            kwargs = {
                "streaming": False,
                "token": config.hf_token,
                "download_config": DownloadConfig(max_retries=10),
                "keep_in_memory": True,
                "verification_mode": "no_checks",
            }
            if src.dataset_id == "librispeech_asr" and (src.config_name or "") == "clean":
                if src.split in ("train.360", "train.100", "validation", "test"):
                    ds = load_dataset(
                        src.dataset_id,
                        src.config_name,
                        data_files={src.split: f"clean/{src.split}/*.parquet"},
                        split=src.split,
                        **kwargs,
                    )
                else:
                    ds = load_dataset(src.dataset_id, src.config_name, split=src.split, **kwargs)
            elif src.dataset_id in ("istupakov/russian_librispeech", "amaai-lab/DisfluencySpeech"):
                # Avoid decoding audio during prefetch; just resolve without touching samples.
                ds = load_dataset(src.dataset_id, src.config_name, split=src.split, **kwargs)
            else:
                ds = load_dataset(src.dataset_id, src.config_name, split=src.split, **kwargs)
            # Do not access samples here to avoid triggering audio decode
            print(f"[prefetch] ok: {label}")
        except Exception as e:
            print(f"[prefetch] failed: {label} | {e}")


def main() -> None:
    config = TrainingConfig()
    # 1) Prefetch datasets to local cache first (avoid streaming timeouts)
    prefetch_all_datasets(config)
    # 2) Instantiate trainer and start MLflow after prefetch
    trainer = Trainer(config)
    trainer.start_logging()
    # 3) Train
    trainer.train()


if __name__ == "__main__":
    main()

