                start = max(0, (arr.shape[0] - target_len) // 2)
            arr = arr[start : start + target_len]
        audios.append(arr.astype(np.float32))
        texts.append(str(item["text"]))

    inputs = processor(
        text=texts,
        audios=audios,
        sampling_rate=AUDIO_SAMPLING_RATE,
        return_tensors="pt",
        padding=True,
        truncation=True,
        max_length=max_text_len or CURRENT_TEXT_MAX_LEN,
    )
    return inputs


# -----------------------------------------------------------------------------
# JamendoMaxCaps dataset helpers (cache discovery and local shard loading)
# -----------------------------------------------------------------------------

def _possible_jamendo_snapshot_dirs() -> List[Path]:
    """Enumerate local Hugging Face snapshot data directories for JamendoMaxCaps."""

    data_dirs: List[Path] = []
    direct_overrides: List[Path] = []

    env_override = os.environ.get("JAMENDO_SNAPSHOT_DIR")
    if env_override:
        override_path = Path(env_override).expanduser()
        if (override_path / "data").is_dir():
            direct_overrides.append((override_path / "data").resolve())
        if override_path.is_dir():
            direct_overrides.append(override_path.resolve())
    if JAMENDO_LOCAL_SNAPSHOT_DIR is not None:
        override_path = Path(JAMENDO_LOCAL_SNAPSHOT_DIR).expanduser()
        if (override_path / "data").is_dir():
            direct_overrides.append((override_path / "data").resolve())
        if override_path.is_dir():
            direct_overrides.append(override_path.resolve())

    raw_bases: List[Path] = []
    env_candidates = [
        os.environ.get("HF_HOME"),
        os.environ.get("HF_DATASETS_CACHE"),
    ]
    for raw in env_candidates:
        if raw:
            raw_bases.append(Path(raw).expanduser())
    raw_bases.append(Path.home() / ".cache/huggingface")

    scan_roots: List[Path] = []
    seen_roots: set[Path] = set()
    for base in raw_bases:
        for candidate in (base, base / "hub", base / "datasets"):
            if not candidate.exists():
                continue
            resolved = candidate.resolve()
            if resolved in seen_roots:
                continue
            seen_roots.add(resolved)
            scan_roots.append(resolved)

    for root in direct_overrides:
        if root.is_dir():
            scan_roots.append(root)

    for base in scan_roots:
        if base.name.startswith("datasets--amaai-lab--JamendoMaxCaps"):
            snapshot_root = base
        else:
            snapshot_root = base / "datasets--amaai-lab--JamendoMaxCaps" / "snapshots"
        if not snapshot_root.exists():
            continue
        try:
            for child in snapshot_root.iterdir():
                data_dir = child / "data"
                if data_dir.exists():
                    data_dirs.append(data_dir.resolve())
        except Exception:
            continue

    data_dirs.extend(direct_overrides)

    unique_dirs: List[Path] = []
    seen_dirs: set[Path] = set()
    for path in sorted(
        data_dirs,
        key=lambda p: p.stat().st_mtime if p.exists() else 0,
        reverse=True,
    ):
        if not path.exists():
            continue
        candidate = path / "data" if (path / "data").is_dir() else path
        if not candidate.exists():
            continue
        if not any(candidate.glob("train-*.parquet")):
            continue
        if candidate in seen_dirs:
            continue
        seen_dirs.add(candidate)
        unique_dirs.append(candidate)
    return unique_dirs


def _resolve_jamendo_local_data_dir() -> Optional[Path]:
    candidates = _possible_jamendo_snapshot_dirs()
    if not candidates:
        return None
    return candidates[0]


def _jamendo_parquet_index(path: Path) -> int:
    parts = path.stem.split("-")
    for token in parts[1:]:
        if token.isdigit():
            try:
                return int(token)
            except ValueError:
                continue
    return 10**9


def _load_jamendo_from_local_shards() -> Optional[Any]:
    """Construct a dataset from whatever Jamendo parquet shards exist locally."""
    candidates = _possible_jamendo_snapshot_dirs()
    if not candidates:
        print("Jamendo cache-only: no local Hugging Face snapshot found.")
        return None
    data_dir = candidates[0]
    if len(candidates) > 1:
        print(
            "Jamendo cache-only: using snapshot "
            f"{data_dir} (other candidates: {', '.join(str(p) for p in candidates[1:])})"
        )
    else:
        print(f"Jamendo cache-only: using snapshot {data_dir}")
    parquet_files = sorted(
        data_dir.glob("train-*.parquet"),
        key=_jamendo_parquet_index,
    )
    total_local_shards = len(parquet_files)
    if JAMENDO_LOCAL_MAX_SHARDS is not None and JAMENDO_LOCAL_MAX_SHARDS > 0:
        if total_local_shards > JAMENDO_LOCAL_MAX_SHARDS:
            print(
                "Jamendo cache-only: limiting to "
                f"{JAMENDO_LOCAL_MAX_SHARDS} shards out of {total_local_shards} available."
            )
        parquet_files = parquet_files[:JAMENDO_LOCAL_MAX_SHARDS]
    if not parquet_files:
        print(f"Jamendo cache-only: snapshot at {data_dir} has no train shards.")
        return None
    available_count = len(parquet_files)
    desired_count = available_count
    unmet_target = None
    if 0.0 < JAMENDO_DATASET_FRACTION < 1.0:
        target = max(1, int(round(JAMENDO_TOTAL_SHARDS * JAMENDO_DATASET_FRACTION)))
        if target < available_count:
            desired_count = target
        else:
            unmet_target = target
    selected_files = parquet_files[:desired_count]
    try:
        dataset_dict = load_dataset(
            "parquet",
            data_files={"train": [str(path) for path in selected_files]},
        )
        hf_ds = dataset_dict["train"]
    except Exception as exc:
        raise RuntimeError(
            "Jamendo cache-only: failed to materialize dataset from local parquet shards "
            f"({len(selected_files)} files under {data_dir}). "
            f"Underlying error: {exc}"
        ) from exc
    if unmet_target is None and 0.0 < JAMENDO_DATASET_FRACTION < 1.0 and desired_count < available_count:
        print(
            "Jamendo cache-only: "
            f"using first {desired_count} of {available_count} local shards "
            f"({JAMENDO_DATASET_FRACTION:.0%} target)."
        )
    if unmet_target is not None:
        print(
            "Jamendo cache-only: "
            f"found only {available_count} local shards (< desired {unmet_target})."
        )
    print(
        "Jamendo cache-only: loaded "
        f"{len(selected_files)} shards ({len(hf_ds)} rows) from {data_dir}"
    )
    return hf_ds


class JamendoMaxCapsDataset(Dataset):
    """Dataset wrapper for amaai-lab/JamendoMaxCaps with robust field access."""

    def __init__(self, hf_dataset, caption_by_id: Dict[str, str]):
        self.ds = hf_dataset
        self.caption_by_id = caption_by_id

    def __len__(self) -> int:
        return len(self.ds)

    def __getitem__(self, index: int) -> Dict[str, torch.Tensor]:
        row = self.ds[index]
        audio = None
        if "audio" in row:
            audio = row["audio"]
        else:
            for key, value in row.items():
                if isinstance(value, dict) and (
                    "array" in value or "path" in value
                ) and ("sampling_rate" in value or "path" in value):
                    audio = value
                    break
        if audio is None:
            audio = {
                "array": np.zeros(int(AUDIO_SAMPLING_RATE * CLIP_SECONDS), dtype=np.float32),
                "sampling_rate": AUDIO_SAMPLING_RATE,
                "path": row.get("path", ""),
            }
        song_id = None
        if isinstance(audio, dict) and audio.get("path"):
            song_id = Path(str(audio["path"])).stem
        text = (
            self.caption_by_id.get(song_id or "")
            or row.get("caption")
            or row.get("generated_caption")
            or row.get("description")
            or row.get("text")
            or "instrumental music track"
        )
        return {"audio": audio, "text": text}


class SongDescriberDataset(Dataset):
    """renumics/song-describer-dataset: uses `audio` + `caption` fields."""

    def __init__(self, hf_dataset):
