        }
        return {"audio": audio, "text": text}


def _build_jamendo_caption_map() -> Dict[str, str]:
    """Fetch supplemental caption jsonl and build song_id->caption map."""

    try:
        url = "https://huggingface.co/datasets/amaai-lab/JamendoMaxCaps/resolve/main/final_caption30sec.jsonl?download=true"
        if JAMENDO_CACHE_ONLY:
            prev_offline = os.environ.get("HF_DATASETS_OFFLINE")
            os.environ["HF_DATASETS_OFFLINE"] = "1"
            try:
                supplemental = load_dataset(
                    "json",
                    data_files=url,
                    split="train",
                    download_mode="reuse_cache_if_exists",
                )
            finally:
                if prev_offline is None:
                    os.environ.pop("HF_DATASETS_OFFLINE", None)
                else:
                    os.environ["HF_DATASETS_OFFLINE"] = prev_offline
        else:
            supplemental = load_dataset(
                "json",
                data_files=url,
                split="train",
                download_mode="reuse_cache_if_exists",
            )
    except Exception:
        return {}
    best_by_id: Dict[str, str] = {}
    for row in supplemental:
        song_id = str(row.get("id", "")).strip()
        caption = str(row.get("caption", "")).strip()
        if not song_id or not caption:
            continue
        current = best_by_id.get(song_id)
        if current is None or len(caption) > len(current):
            best_by_id[song_id] = caption
    return best_by_id


def compute_accuracy(logits: torch.Tensor) -> float:
    predictions = logits.argmax(dim=-1)
    targets = torch.arange(predictions.shape[0], device=predictions.device)
    correct = (predictions == targets).float().mean().item()
    return correct


@dataclass
class Metrics:
    loss: float
    accuracy: float


def evaluate(
    model: ClapModel,
    loader: DataLoader,
    device: torch.device,
    *,
    desc: Optional[str] = None,
) -> Metrics:
    model.eval()
    total_loss = 0.0
    total_accuracy = 0.0
    steps = 0
    progress_desc = desc or "Validation"
    try:
        total_batches: Optional[int] = len(loader)
    except TypeError:
        total_batches = None
    progress_bar = tqdm(
        loader,
        desc=progress_desc,
        unit="batch",
        leave=False,
        total=total_batches,
    )
    with torch.no_grad():
        for batch in progress_bar:
            batch = {k: v.to(device) for k, v in batch.items()}
            outputs = model(**batch, return_loss=True)
            total_loss += outputs.loss.item()
            total_accuracy += compute_accuracy(outputs.logits_per_text)
            steps += 1
            avg_loss = total_loss / steps
            avg_accuracy = total_accuracy / steps
            progress_bar.set_postfix(
                loss=f"{avg_loss:.4f}",
                acc=f"{avg_accuracy:.4f}",
            )
    progress_bar.close()
    if steps == 0:
        return Metrics(loss=0.0, accuracy=0.0)
    return Metrics(loss=total_loss / steps, accuracy=total_accuracy / steps)


def save_checkpoint(
    model: ClapModel,
    processor: AutoProcessor,
    target_dir: Path,
) -> None:
    if target_dir.exists():
        shutil.rmtree(target_dir)
    target_dir.mkdir(parents=True, exist_ok=True)
    model.save_pretrained(target_dir)
    processor.save_pretrained(target_dir)
    print(f"Saved checkpoint: {target_dir}")


def train(
    model: ClapModel,
    processor: AutoProcessor,
    train_loader: DataLoader,
    val_loader: DataLoader,
    device: torch.device,
    initial_best_val_accuracy: Optional[float] = None,
    initial_global_step: int = 0,
) -> float:
    optimizer = AdamW(model.parameters(), lr=LEARNING_RATE, weight_decay=WEIGHT_DECAY)
    model.to(device)
    global _SCHEDULE_ACTIVE, CURRENT_AUDIO_SECONDS, CURRENT_TEXT_MAX_LEN
    _SCHEDULE_ACTIVE = True
    best_val_accuracy = (
        initial_best_val_accuracy if initial_best_val_accuracy is not None else -float("inf")
    )
    global_step = initial_global_step

    CHECKPOINT_DIR.mkdir(parents=True, exist_ok=True)

    epoch_bar = tqdm(
        range(NUM_EPOCHS),
        desc="Epochs",
        unit="epoch",
    )
    for epoch_index in epoch_bar:
        epoch_number = epoch_index + 1
        model.train()
        running_loss = 0.0
        step_count = 0
        try:
            total_train_batches: Optional[int] = len(train_loader)
        except TypeError:
            total_train_batches = None
        train_bar = tqdm(
            train_loader,
            desc=f"Train {epoch_number}/{NUM_EPOCHS}",
            unit="batch",
            leave=False,
            total=total_train_batches,
        )
        for batch in train_bar:
            batch = {k: v.to(device) for k, v in batch.items()}
            outputs = model(**batch, return_loss=True)
            loss = outputs.loss / GRADIENT_ACCUMULATION_STEPS
            loss.backward()
            if (step_count + 1) % GRADIENT_ACCUMULATION_STEPS == 0:
                optimizer.step()
                optimizer.zero_grad()
            batch_loss = outputs.loss.item()
            running_loss += batch_loss
            step_count += 1
            global_step += 1

            avg_loss = running_loss / max(1, step_count)
            train_bar.set_postfix(
                loss=f"{batch_loss:.4f}",
                avg_loss=f"{avg_loss:.4f}",
            )

            if TRAIN_LOG_EVERY_STEPS and global_step % TRAIN_LOG_EVERY_STEPS == 0:
                train_accuracy = compute_accuracy(outputs.logits_per_text.detach())
                mlflow.log_metric("train_loss_step", batch_loss, step=global_step)
                mlflow.log_metric("train_accuracy_step", train_accuracy, step=global_step)

        if step_count % GRADIENT_ACCUMULATION_STEPS != 0:
            optimizer.step()
            optimizer.zero_grad()

        avg_train_loss = running_loss / max(1, step_count)
        mlflow.log_metric("train_loss", avg_train_loss, step=epoch_number)
        prev_schedule_state = _enter_eval_limits()
        metrics = evaluate(
            model,
            val_loader,
            device,
            desc=f"Val {epoch_number}/{NUM_EPOCHS}",
        )
        _exit_eval_limits(prev_schedule_state)
        train_bar.close()
        tqdm.write(
            f"epoch={epoch_number}/{NUM_EPOCHS} train_loss={avg_train_loss:.4f} "
            f"val_loss={metrics.loss:.4f} val_acc={metrics.accuracy:.4f}"
        )
        epoch_bar.set_postfix(
            train_loss=f"{avg_train_loss:.4f}",
            val_acc=f"{metrics.accuracy:.4f}",
        )
        mlflow.log_metric("val_loss", metrics.loss, step=epoch_number)
        mlflow.log_metric("val_accuracy", metrics.accuracy, step=epoch_number)

        if metrics.accuracy > best_val_accuracy:
            best_val_accuracy = metrics.accuracy
            save_checkpoint(model, processor, BEST_CHECKPOINT_DIR)

    epoch_bar.close()
    return best_val_accuracy

def build_loaders(processor: AutoProcessor, sample_limit: Optional[int] = None) -> Dict[str, DataLoader]:
    """Construct train/val loaders for the chosen DATASET_SOURCE and configure the context growth schedule."""

    global SCHEDULE, CURRENT_AUDIO_SECONDS, CURRENT_TEXT_MAX_LEN, _SCHEDULE_COLLATE_STEP

    tokenizer = getattr(processor, "tokenizer", None)

    def encode_lengths(texts: Sequence[str], limit: int = 2000) -> List[int]:
        if tokenizer is None:
            return []
        lengths: List[int] = []
        for text in texts[:limit]:
            try:
                encoded = tokenizer(
                    text,
                    add_special_tokens=True,
                    return_attention_mask=False,
                    return_token_type_ids=False,
                )
                lengths.append(len(encoded["input_ids"]))
            except Exception:
                continue
        return lengths

    audio_target = CLIP_SECONDS
    text_target = TEXT_START_MAX_LEN

    if DATASET_SOURCE == "jamendomaxcaps":
        jamendo_cache_path = JAMENDO_DATASET_CACHE_DIR
        jamendo_cache_path.parent.mkdir(parents=True, exist_ok=True)

        # Compute a HF split selector that limits downloads up-front
        if 0.0 < JAMENDO_DATASET_FRACTION < 1.0:
            frac_percent = max(1, int(round(JAMENDO_DATASET_FRACTION * 100)))
            split_spec = f"train[:{frac_percent}%]"
        else:
            split_spec = "train"

        hf_ds = None

        # If streaming is enabled, bypass disk cache and iterate the split directly
        if JAMENDO_STREAMING and not JAMENDO_CACHE_ONLY:
            print("JamendoMaxCaps: streaming mode active. No Arrow cache on disk.")
            # Try to fetch dataset metadata to compute an exact target row count
            total_examples: Optional[int] = None
            try:
                cfg_names = get_dataset_config_names("amaai-lab/JamendoMaxCaps")
                cfg = cfg_names[0] if cfg_names else None
                info = get_dataset_config_info("amaai-lab/JamendoMaxCaps", config_name=cfg)
                if info and getattr(info, "splits", None) and "train" in info.splits:
                    total_examples = info.splits["train"].num_examples
            except Exception:
                total_examples = None

            target_rows: Optional[int] = None
            if 0.0 < JAMENDO_DATASET_FRACTION < 1.0 and total_examples:
                target_rows = max(1, int(round(total_examples * JAMENDO_DATASET_FRACTION)))
            elif JAMENDO_STREAM_MAX_ROWS is not None and JAMENDO_STREAM_MAX_ROWS > 0:
                target_rows = JAMENDO_STREAM_MAX_ROWS

            stream = load_dataset("amaai-lab/JamendoMaxCaps", split="train", streaming=True)

            # Partition approximately 90/10 into train/val while iterating once
            train_rows: List[Dict[str, Any]] = []
            val_rows: List[Dict[str, Any]] = []
            cnt = 0
            for row in stream:  # type: ignore[assignment]
                (val_rows if (cnt % 10 == 0) else train_rows).append(row)
                cnt += 1
                if target_rows is not None and cnt >= target_rows:
                    break
            total_rows = cnt
            if total_rows == 0:
                raise RuntimeError("JamendoMaxCaps stream returned no samples.")
            caption_map = _build_jamendo_caption_map()
            train_ds = train_rows
            val_ds = val_rows
        else:
            # Prefer a previously saved small subset cache to avoid any re-download
            if jamendo_cache_path.exists() and not JAMENDO_CACHE_ONLY:
                try:
                    hf_ds = load_from_disk(str(jamendo_cache_path))
                    print(f"Loaded JamendoMaxCaps subset cache from {jamendo_cache_path}")
                except Exception as exc:
                    print(f"Failed to load JamendoMaxCaps cache at {jamendo_cache_path}: {exc}")
                    hf_ds = None

            if hf_ds is None:
                if JAMENDO_CACHE_ONLY:
                    hf_ds = _load_jamendo_from_local_shards()
                    if hf_ds is None:
                        candidates = _possible_jamendo_snapshot_dirs()
                        raise RuntimeError(
                            "Cache-only mode: no local JamendoMaxCaps parquet shards found. "
                            "Disable JAMENDO_CACHE_ONLY to allow downloading, or ensure shards exist in HF cache. "
                            f"Scanned snapshot data dirs: {candidates or 'none found'}."
                        )
                else:
                    # This enforces the fraction during download
                    hf_ds = load_dataset("amaai-lab/JamendoMaxCaps", split=split_spec)
                    # Persist the small subset to disk for next run
                    if jamendo_cache_path.exists():
                        shutil.rmtree(jamendo_cache_path, ignore_errors=True)
                    hf_ds.save_to_disk(str(jamendo_cache_path))
                    print(f"Saved JamendoMaxCaps subset to cache at {jamendo_cache_path}")

            current_rows = len(hf_ds)
            print(f"JamendoMaxCaps subset ready with {current_rows} rows (split='{split_spec}')")
            if sample_limit is not None and sample_limit < len(hf_ds):
                hf_ds = hf_ds.select(range(sample_limit))
            total_rows = len(hf_ds)
            if total_rows == 0:
                raise RuntimeError("JamendoMaxCaps dataset returned no samples.")
            caption_map = _build_jamendo_caption_map()
            if total_rows < 2:
                train_ds = hf_ds
                val_ds = hf_ds.select([])
            else:
                pivot = max(1, int(total_rows * 0.9))
                if pivot >= total_rows:
                    pivot = total_rows - 1
                train_ds = hf_ds.select(range(0, pivot))
                val_ds = hf_ds.select(range(pivot, total_rows))

        # Wrap into Dataset objects
        train_dataset = JamendoMaxCapsDataset(train_ds, caption_map)
        val_dataset = JamendoMaxCapsDataset(val_ds, caption_map)

        scan_n = min(1024, len(train_ds))
        dur_seconds: List[float] = []
        text_candidates: List[str] = []
        for idx in range(scan_n):
            row = train_ds[idx]
            audio = row.get("audio")
            if isinstance(audio, dict):
                array = audio.get("array")
                sr = audio.get("sampling_rate")
                if array is not None and sr:
                    samples = np.asarray(array)
                    if samples.size > 0:
                        dur_seconds.append(samples.shape[0] / float(sr))
                path_str = audio.get("path")
            else:
                path_str = row.get("path")
            song_id = Path(str(path_str)).stem if path_str else ""
            caption = (
                caption_map.get(song_id)
                or row.get("caption")
                or row.get("generated_caption")
                or row.get("description")
                or row.get("text")
                or ""
            )
            if caption:
                text_candidates.append(str(caption))
        if dur_seconds:
            audio_target = int(
                min(
                    AUDIO_TARGET_MAX_SECONDS_CAP,
                    max(CLIP_SECONDS, int(round(float(np.percentile(dur_seconds, 95))))),
                )
            )
        if text_candidates:
            text_lengths = encode_lengths(text_candidates)
            if text_lengths:
                text_target = int(
                    min(
                        TEXT_TARGET_MAX_LEN_CAP,
                        max(TEXT_START_MAX_LEN, max(text_lengths)),
                    )
                )

    elif DATASET_SOURCE == "song_describer":
        hf_ds = load_dataset("renumics/song-describer-dataset", split="train")
        if sample_limit is not None and sample_limit < len(hf_ds):
            hf_ds = hf_ds.select(range(sample_limit))
        total_rows = len(hf_ds)
        if total_rows == 0:
            raise RuntimeError("Song-Describer dataset returned no samples.")
        if total_rows < 2:
            train_ds = hf_ds
            val_ds = hf_ds.select([])
        else:
            pivot = max(1, int(total_rows * 0.9))
            if pivot >= total_rows:
                pivot = total_rows - 1
