    return "instrumental music track"


def _resolve_audio_path(path_str: str) -> str:
    candidate = path_str.strip()
    if os.path.exists(candidate):
        return candidate
    filename = candidate.split("/")[-1].split("?")[0]
    if DATASET_SOURCE == "jamendomaxcaps":
        if not filename.startswith("audio/"):
            filename = f"audio/{filename}"
        try:
