                repo_id=JAMENDO_DATASET_ID,
                filename=filename,
                repo_type="dataset",
            )
        except EntryNotFoundError as exc:
            raise MissingAudioError(f"Jamendo audio file missing on Hugging Face: {filename}") from exc
    raise FileNotFoundError(f"Audio file not found locally: {path_str}")


