    end_idx = int(np.ceil(total * end_frac))
    end_idx = max(start_idx + 1, end_idx)
    end_idx = min(end_idx, total)
    filenames = [
        f"train-{idx:0{JAMENDO_SHARD_PAD}d}-of-{JAMENDO_TOTAL_SHARDS:0{JAMENDO_SHARD_PAD}d}.parquet"
        for idx in range(start_idx, end_idx)
    ]
    if not filenames:
        raise ValueError("Jamendo shard window produced no files. Check SUBSET_* settings.")
