class JamendoIterableDataset(IterableDataset):
    def __init__(self, iterable: Iterable[Dict]):
        self.iterable = iterable

    def __iter__(self) -> Iterator[Dict[str, object]]:
        for row in self.iterable:
            audio_info = row.get("audio")
            if not isinstance(audio_info, dict):
                raise ValueError("Jamendo streaming row missing audio metadata.")
            yield {
                "audio": audio_info,
                "text": _extract_caption(row),
            }


