        row = self.dataset[index]
        audio_info = row.get("audio")
        if not isinstance(audio_info, dict):
            raise ValueError("Jamendo sample missing audio metadata.")
        return {
            "audio": audio_info,
            "text": _extract_caption(row),
        }


class SongDescriberDataset(Dataset):
    def __init__(self, dataset):
        self.dataset = dataset

    def __len__(self) -> int:
        return len(self.dataset)

    def __getitem__(self, index: int) -> Dict[str, object]:
        row = self.dataset[index]
        audio = row.get("audio")
        if audio is None:
            for value in row.values():
                if isinstance(value, dict) and ("path" in value or "array" in value):
                    audio = value
                    break
        if audio is None:
            raise ValueError("Song-Describer sample missing audio data.")
        text = row.get("caption") or row.get("description") or row.get("text") or ""
        return {"audio": audio, "text": text}


