def _build_jamendo_streaming_dataset() -> tuple[IterableDataset, IterableDataset, List[float], List[str]]:
    filenames = _jamendo_shard_filenames(SUBSET_START_FRAC, SUBSET_END_FRAC)
    urls = _jamendo_shard_urls(filenames)
    shard_count = len(urls)
    if shard_count == 0:
        raise ValueError("Jamendo streaming selection resulted in zero shards.")

    if shard_count == 1:
        val_count = 0
    else:
        val_count = int(np.ceil(shard_count * VALIDATION_FRACTION))
        val_count = max(1, min(val_count, shard_count - 1))

    val_urls = urls[:val_count]
    train_urls = urls[val_count:]

    data_files: Dict[str, List[str]] = {"train": train_urls}
    if val_urls:
        data_files["validation"] = val_urls

    dataset_dict = load_dataset("parquet", data_files=data_files, streaming=True)
    train_stream = dataset_dict["train"]
    val_stream_iterable = dataset_dict.get("validation") if val_urls else []

    durations: List[float] = []
    texts: List[str] = []
    if train_urls:
        scan_stream = load_dataset("parquet", data_files={"train": train_urls}, streaming=True)["train"]
        for idx, row in enumerate(scan_stream):
            if idx >= SCHEDULE_SCAN_LIMIT:
                break
            duration = _infer_audio_duration(row.get("audio"))
            if duration:
                durations.append(duration)
            texts.append(_extract_caption(row))

    print(
        "Streaming Jamendo shards: "
        f"total_shards={JAMENDO_TOTAL_SHARDS}, selected={shard_count}, "
        f"train_shards={len(train_urls)}, val_shards={len(val_urls)}, "
        f"range=[{filenames[0]} .. {filenames[-1]}]"
    )
    return JamendoIterableDataset(train_stream), JamendoIterableDataset(val_stream_iterable), durations, texts


class JamendoShardStreamDataset(IterableDataset):
    """Iterates Jamendo shards one-by-one from local temp files.

    For each filename in `filenames`, downloads the parquet shard to a temp dir,
    streams rows from that local file via datasets(parquet, streaming=True), and
    deletes the file when that shard is exhausted. This avoids Arrow cache writes
    and keeps disk usage bounded to a single shard.
    """

    def __init__(self, filenames: List[str], temp_dir: Path):
        self.filenames = list(filenames)
        self.temp_dir = Path(temp_dir)
        self.temp_dir.mkdir(parents=True, exist_ok=True)

    def __iter__(self):
        for name in self.filenames:
            local_path = hf_hub_download(
                repo_id=JAMENDO_DATASET_ID,
                filename=f"data/{name}",
                repo_type="dataset",
                local_dir=str(self.temp_dir),
                local_dir_use_symlinks=False,
            )
            ds = load_dataset("parquet", data_files={"train": [local_path]}, streaming=True)["train"]
            # rows already have the same schema as jamendo parquet; keep audio undecoded
            for row in ds:
                yield {"audio": row.get("audio"), "text": _extract_caption(row)}
            try:
                os.remove(local_path)
            except OSError:
                pass


def _build_jamendo_cached_dataset() -> tuple[Dataset, Dataset, List[float], List[str]]:
    filenames = _jamendo_shard_filenames(SUBSET_START_FRAC, SUBSET_END_FRAC)
    shard_count = len(filenames)
    if shard_count == 0:
        raise ValueError("Jamendo cached selection resulted in zero shards.")

    if shard_count == 1:
        val_count = 0
    else:
        val_count = int(np.ceil(shard_count * VALIDATION_FRACTION))
        val_count = max(1, min(val_count, shard_count - 1))

    val_files = filenames[:val_count]
    train_files = filenames[val_count:]

    # Build shard-wise iterable datasets that handle download->iterate->delete
    tmp_root = Path("data/jamendo_tmp")
    train_ds = JamendoShardStreamDataset(train_files or val_files, tmp_root / "train")
    val_ds = JamendoShardStreamDataset(val_files, tmp_root / "val") if train_files else JamendoShardStreamDataset([], tmp_root / "val")

    # For schedule targets, scan a small sample from the first training shard
    durations: List[float] = []
    texts: List[str] = []
    if train_files:
        first = train_files[0]
        local_path = hf_hub_download(
            repo_id=JAMENDO_DATASET_ID,
            filename=f"data/{first}",
            repo_type="dataset",
            local_dir=str(tmp_root / "scan"),
            local_dir_use_symlinks=False,
        )
        scan_stream = load_dataset("parquet", data_files={"train": [local_path]}, streaming=True)["train"]
        for idx, row in enumerate(scan_stream):
            if idx >= SCHEDULE_SCAN_LIMIT:
                break
            d = _infer_audio_duration(row.get("audio"))
            if d:
                durations.append(d)
            texts.append(_extract_caption(row))
        try:
            os.remove(local_path)
        except OSError:
            pass

    print(
        "Shard-wise Jamendo (bounded disk): "
        f"total_shards={JAMENDO_TOTAL_SHARDS}, selected={shard_count}, "
        f"train_shards={len(train_files) if train_files else len(filenames)}, val_shards={len(val_files)}, "
        f"range=[{filenames[0]} .. {filenames[-1]}]"
    )
    return train_ds, val_ds, durations, texts


