def build_loaders(processor: AutoProcessor) -> Dict[str, DataLoader]:
    global SCHEDULE, CURRENT_AUDIO_SECONDS, CURRENT_TEXT_MAX_LEN, _SCHEDULE_COLLATE_STEP, _SCHEDULE_ACTIVE

    _validate_fraction_range(SUBSET_START_FRAC, SUBSET_END_FRAC)

    if DATASET_SOURCE == "jamendomaxcaps":
        if STREAMING:
            train_dataset, val_dataset, durations, texts = _build_jamendo_streaming_dataset()
        else:
            train_dataset, val_dataset, durations, texts = _build_jamendo_cached_dataset()
    elif DATASET_SOURCE == "song_describer":
        train_dataset, val_dataset, durations, texts = _build_song_describer_dataset()
    elif DATASET_SOURCE == "music4all":
        train_dataset, val_dataset, durations, texts = _build_music4all_dataset()
    else:
        raise ValueError(f"Unsupported DATASET_SOURCE: {DATASET_SOURCE}")

    tokenizer = getattr(processor, "tokenizer", None)
    audio_target, text_target = _schedule_targets_from_samples(durations, texts, tokenizer)

    collate = lambda batch: collate_batch(batch, processor)

    train_loader = DataLoader(
        train_dataset,
        batch_size=TRAIN_BATCH_SIZE,
        shuffle=False if isinstance(train_dataset, IterableDataset) else True,
        collate_fn=collate,
    )
    val_loader = DataLoader(
        val_dataset,
        batch_size=EVAL_BATCH_SIZE,
        shuffle=False,
        collate_fn=collate,
    )

    try:
        steps_per_epoch = len(train_loader)
    except TypeError:
        steps_per_epoch = 0
    planned_total = max(1, steps_per_epoch * NUM_EPOCHS)
    growth_steps = int(planned_total * CONTEXT_GROWTH_FRACTION)

    SCHEDULE = ContextSchedule(
        audio_start_s=CLIP_SECONDS,
        audio_target_s=int(audio_target),
        text_start_tok=TEXT_START_MAX_LEN,
        text_target_tok=int(text_target),
        growth_steps=growth_steps,
    )
    CURRENT_AUDIO_SECONDS = CLIP_SECONDS
    CURRENT_TEXT_MAX_LEN = TEXT_START_MAX_LEN
    _SCHEDULE_COLLATE_STEP = 0
    _SCHEDULE_ACTIVE = True

    return {"train": train_loader, "val": val_loader}


