def collate_batch(batch: List[Dict[str, object]], processor: AutoProcessor) -> Dict[str, torch.Tensor]:
    _schedule_next_limits()
    target_len = int(AUDIO_SAMPLING_RATE * CURRENT_AUDIO_SECONDS)

    audios: List[np.ndarray] = []
    texts: List[str] = []

    for item in batch:
        audio_entry = item.get("audio")
        try:
            arr, sampling_rate = _load_audio_entry(audio_entry)
        except MissingAudioError as exc:
            print(f"Skipping sample with missing audio: {exc}")
            continue
        if arr.ndim > 1:
            arr = arr.mean(axis=-1)
        if sampling_rate != AUDIO_SAMPLING_RATE and arr.size > 0:
            arr = librosa.resample(arr, orig_sr=sampling_rate, target_sr=AUDIO_SAMPLING_RATE)
        if arr.shape[0] < target_len:
            arr = np.pad(arr, (0, target_len - arr.shape[0]))
        elif arr.shape[0] > target_len:
            max_start = arr.shape[0] - target_len
            if _SCHEDULE_ACTIVE and max_start > 0:
                start = np.random.randint(0, max_start + 1)
            else:
                start = max(0, max_start // 2)
            arr = arr[start : start + target_len]
        audios.append(arr.astype(np.float32))
        texts.append(str(item.get("text", "")))

    if not audios:
        print("Warning: batch contained only missing audio; inserting silence placeholder.")
        audios.append(np.zeros(target_len, dtype=np.float32))
        texts.append("instrumental music track")

    text_inputs = processor(
        text=texts,
        return_tensors="pt",
        padding=True,
        truncation=True,
        max_length=CURRENT_TEXT_MAX_LEN,
    )
    audio_inputs = processor.feature_extractor(
        audios=audios,
        sampling_rate=AUDIO_SAMPLING_RATE,
        return_tensors="pt",
        padding=False,
        truncation=False,
    )

    return {
        "input_ids": text_inputs["input_ids"],
        "attention_mask": text_inputs.get("attention_mask"),
        "input_features": audio_inputs["input_features"],
    }


def save_checkpoint(model: ClapModel, processor: AutoProcessor, target_dir: Path) -> None:
    if target_dir.exists():
        shutil.rmtree(target_dir)
    target_dir.mkdir(parents=True, exist_ok=True)
    model.save_pretrained(target_dir)
    processor.save_pretrained(target_dir)
    print(f"Saved checkpoint: {target_dir}")


def compute_accuracy(logits: torch.Tensor) -> float:
    predictions = logits.argmax(dim=-1)
    targets = torch.arange(predictions.shape[0], device=predictions.device)
    return (predictions == targets).float().mean().item()


def evaluate(model: ClapModel, loader: DataLoader, device: torch.device, desc: str) -> Metrics:
    model.eval()
    total_loss = 0.0
    total_accuracy = 0.0
    steps = 0
    try:
        total_batches: Optional[int] = len(loader)
    except TypeError:
        total_batches = None

    progress = tqdm(loader, desc=desc, leave=False, total=total_batches)
    with torch.no_grad():
        for batch in progress:
            batch = {k: v.to(device) for k, v in batch.items() if v is not None}
            outputs = model(**batch, return_loss=True)
            total_loss += outputs.loss.item()
            total_accuracy += compute_accuracy(outputs.logits_per_text)
            steps += 1
            progress.set_postfix(
                loss=f"{total_loss / steps:.4f}",
                acc=f"{total_accuracy / steps:.4f}",
            )
    progress.close()
    if steps == 0:
        return Metrics(loss=0.0, accuracy=0.0)
    return Metrics(loss=total_loss / steps, accuracy=total_accuracy / steps)


def train_loop(
    model: ClapModel,
    processor: AutoProcessor,
    loaders: Dict[str, DataLoader],
    device: torch.device,
) -> Metrics:
    optimizer = AdamW(model.parameters(), lr=LEARNING_RATE, weight_decay=WEIGHT_DECAY)
    best_metrics = Metrics(loss=float("inf"), accuracy=0.0)
    global_step = 0

    for epoch in range(NUM_EPOCHS):
        model.train()
        running_loss = 0.0
        steps = 0
        try:
            total_batches = len(loaders["train"])
        except TypeError:
            total_batches = None
        train_progress = tqdm(
            loaders["train"],
            desc=f"Train epoch {epoch + 1}/{NUM_EPOCHS}",
            leave=False,
            total=total_batches,
        )
        for batch in train_progress:
            batch = {k: v.to(device) for k, v in batch.items() if v is not None}
            outputs = model(**batch, return_loss=True)
            loss = outputs.loss / GRADIENT_ACCUMULATION_STEPS
            loss.backward()
            if (steps + 1) % GRADIENT_ACCUMULATION_STEPS == 0:
                optimizer.step()
                optimizer.zero_grad()
            running_loss += outputs.loss.item()
            steps += 1
            global_step += 1
            mlflow.log_metric("allowed_audio_seconds", CURRENT_AUDIO_SECONDS, step=global_step)
            mlflow.log_metric("allowed_text_tokens", CURRENT_TEXT_MAX_LEN, step=global_step)
            train_progress.set_postfix(loss=f"{running_loss / max(1, steps):.4f}")
        train_progress.close()

        prev_state = _enter_eval_limits()
        val_metrics = evaluate(model, loaders["val"], device, desc=f"Val epoch {epoch + 1}/{NUM_EPOCHS}")
        _exit_eval_limits(prev_state)

        mlflow.log_metric("train_loss", running_loss / max(1, steps), step=epoch + 1)
        mlflow.log_metric("val_loss", val_metrics.loss, step=epoch + 1)
        mlflow.log_metric("val_accuracy", val_metrics.accuracy, step=epoch + 1)

        if val_metrics.loss < best_metrics.loss:
            best_metrics = val_metrics
            save_checkpoint(model, processor, BEST_CHECKPOINT_DIR)

        print(
            f"Epoch {epoch + 1}: train_loss={running_loss / max(1, steps):.4f} "
            f"val_loss={val_metrics.loss:.4f} val_acc={val_metrics.accuracy:.4f}"
        )

    return best_metrics


