```python
#!/usr/bin/env python3
import os
import subprocess
from pathlib import Path
import pandas as pd
import re
import requests
import sys

REPO_URL = "https://github.com/Maxl94/LyricCovers2.0.git"
REPO_DIR = Path("LyricCovers2.0")
DATA_DIR = REPO_DIR / "data"
OUT_DIR = Path("out")
AUDIO_DIR = OUT_DIR / "audio"
COVERS_DIR = OUT_DIR / "covers"
OUT_CSV = OUT_DIR / "meta.csv"
N_SAMPLES = 1000

def run(cmd, cwd=None):
    print(">>", " ".join(cmd))
    res = subprocess.run(cmd, cwd=cwd, check=False)
    if res.returncode != 0:
        print("!! failed:", cmd, file=sys.stderr)
    return res.returncode == 0

def clone_repo():
    if not REPO_DIR.exists():
        if not run(["git", "clone", REPO_URL]):
            raise SystemExit("git clone failed")
    # если хочешь обновлять: run(["git", "pull"], cwd=str(REPO_DIR))

def pick_data_file():
    if not DATA_DIR.exists():
        raise SystemExit("в репе нет папки data/ — глянь руками")
    # читаем ВСЁ, что там есть
    files = [p for p in DATA_DIR.rglob("*") if p.is_file()]
    if not files:
        raise SystemExit("в data/ нет файлов")
    # порядок: parquet, pkl, csv
    prio_ext = [".parquet", ".pqt", ".pkl", ".pickle", ".csv"]
    # сначала отфильтруем по приоритету
    for ext in prio_ext:
        cand = [p for p in files if p.suffix.lower() == ext]
        if cand:
            # возьмём самый большой из этого типа
            cand.sort(key=lambda p: p.stat().st_size, reverse=True)
            return cand[0]
    # если прям ничего подходящего
    raise SystemExit("нашёл файлы в data/, но ни parquet/pkl/csv")

def load_df(path: Path) -> pd.DataFrame:
    suf = path.suffix.lower()
    if suf in (".parquet", ".pqt"):
        return pd.read_parquet(path)
    if suf in (".pkl", ".pickle"):
        return pd.read_pickle(path)
    if suf == ".csv":
        return pd.read_csv(path)
    raise SystemExit(f"не умею читать {path}")

def extract_youtube_id(url: str):
    if not isinstance(url, str):
        return None
    m = re.search(r"v=([A-Za-z0-9_\-]{6,})", url)
    if m:
        return m.group(1)
    m = re.search(r"youtu\.be/([A-Za-z0-9_\-]{6,})", url)
    if m:
        return m.group(1)
    return None

def download_cover(video_id: str, dest: Path):
    dest.parent.mkdir(parents=True, exist_ok=True)
    urls = [
        f"https://img.youtube.com/vi/{video_id}/maxresdefault.jpg",
        f"https://img.youtube.com/vi/{video_id}/hqdefault.jpg",
    ]
    for u in urls:
        try:
            r = requests.get(u, timeout=15)
            if r.status_code == 200:
                dest.write_bytes(r.content)
                return str(dest)
        except Exception:
            pass
    return None

def download_audio(url: str, dest: Path):
    dest.parent.mkdir(parents=True, exist_ok=True)
    # нужен yt-dlp в PATH
    out_tmpl = str(dest.with_suffix("")) + ".%(ext)s"
    cmd = [
        "yt-dlp",
        "-f", "bestaudio/best",
        "--extract-audio",
        "--audio-format", "mp3",
        "--audio-quality", "0",
        "-o", out_tmpl,
        url,
    ]
    ok = run(cmd)
    if not ok:
        return None
    mp3 = dest.with_suffix(".mp3")
    if mp3.exists():
        return str(mp3)
    # fallback: возьмём первый попавшийся
    for f in dest.parent.glob(dest.stem + ".*"):
        return str(f)
    return None

def main():
    clone_repo()
    data_file = pick_data_file()
    print(f"использую датасет: {data_file}")
    df = load_df(data_file)
    print("колонки:", df.columns.tolist())

    # имя колонки с youtube
    yt_col = None
    for c in ["youtube_url", "url", "youtube", "yt"]:
        if c in df.columns:
            yt_col = c
            break
    if yt_col is None:
        raise SystemExit("в датасете нет youtube_url / url, глянь df.columns")

    if "original_id" not in df.columns:
        raise SystemExit("в датасете нет original_id, но в README он есть — смотри руками")

    # стратификация: берём по 1 из каждой original_id
    df = df.sort_values("original_id")
    groups = df.groupby("original_id")
    rows = []
    for _, g in groups:
        rows.append(g.iloc[0])
        if len(rows) >= N_SAMPLES:
            break
    sample = pd.DataFrame(rows).reset_index(drop=True)

    OUT_DIR.mkdir(exist_ok=True)
    AUDIO_DIR.mkdir(exist_ok=True)
    COVERS_DIR.mkdir(exist_ok=True)

    out_records = []
    for _, row in sample.iterrows():
        tid = str(row.get("id", ""))
        title = row.get("title", "")
        artist = row.get("artist", "")
        lyrics = row.get("lyrics", "")
        orig = row.get("original_id")
        yurl = row.get(yt_col)

        audio_path = None
        cover_path = None

        if isinstance(yurl, str) and yurl.strip():
            audio_path = download_audio(yurl, AUDIO_DIR / f"{tid}.mp3")
            vid = extract_youtube_id(yurl)
            if vid:
                cover_path = download_cover(vid, COVERS_DIR / f"{tid}.jpg")

        out_records.append(
            {
                "id": tid,
                "title": title,
                "artist": artist,
                "lyrics": lyrics,
                "original_id": orig,
                "youtube_url": yurl,
                "audio_path": audio_path,
                "cover_path": cover_path,
            }
        )

    out_df = pd.DataFrame(out_records)
    out_df.to_csv(OUT_CSV, index=False)
    print("готово:", OUT_CSV)

if __name__ == "__main__":
    main()
```

