    func moveToFrame(_ newFrame: CGRect) {
        let slotChanged = isHidden || frame.origin != newFrame.origin
        if slotChanged {
            popIn(to: newFrame)
        } else {
            frame = newFrame
        }
    }

    private func popIn(to target: CGRect) {
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        frame = target.insetBy(dx: target.width * 0.25, dy: target.height * 0.25)
        CATransaction.commit()
        NSAnimationContext.runAnimationGroup { ctx in
            ctx.duration = CanvasStyle.placeholderSlotDuration
            ctx.timingFunction = CAMediaTimingFunction(name: .easeOut)
            self.animator().frame = target
        }
    }

