        return !peers.contains { peer in peer.origin != origin && rect.intersects(peer) }
    }
    let pool = valid.isEmpty ? all : valid

    let raw = pool.min {
        ptDistSq(CGPoint(x: $0.x + offset.x, y: $0.y + offset.y), handle)
            < ptDistSq(CGPoint(x: $1.x + offset.x, y: $1.y + offset.y), handle)
    } ?? pool[0]
    return CGRect(origin: raw, size: floating.size)
}

// settle() but starting from the frame's current origin instead of (margin, margin).
// Only peers that actually block the current position push it; peers above a frame
// that is already below them have no effect.
private func settleFromCurrent(_ frame: CGRect, among others: [CGRect], margin: CGFloat) -> CGPoint {
    var rect = frame
    for _ in 0...(others.count + 1) {
        let origin = rect.origin
        var y = max(margin, rect.minY)
        for other in others where xSpansOverlap(rect, other) && other.minY < rect.minY {
            y = max(y, other.maxY + margin)
        }
        rect.origin.y = y
        var x = max(margin, rect.minX)
        for other in others where ySpansOverlap(rect, other) && other.minX < rect.minX {
            x = max(x, other.maxX + margin)
        }
        rect.origin.x = x
        guard rect.origin != origin else { break }
    }
    for _ in 0...(others.count + 1) {
        guard let hit = others.first(where: { rect.intersects($0) }) else { break }
        if ySpansOverlap(rect, hit), hit.minX < rect.minX {
            rect.origin.x = hit.maxX + margin
        } else {
            rect.origin.y = hit.maxY + margin
        }
    }
    return CGPoint(x: round(rect.origin.x), y: round(rect.origin.y))
}
