       let visible = scrollView.documentVisibleRect
       let zone: CGFloat = 60
       let maxSpeed: CGFloat = 6
       func edgeSpeed(_ v: CGFloat, _ lo: CGFloat, _ hi: CGFloat) -> CGFloat {
           if v < lo + zone { return -maxSpeed * (1 - (v - lo) / zone) }
           if v > hi - zone { return  maxSpeed * (1 - (hi - v) / zone) }
           return 0
       }
       let dx = edgeSpeed(cursor.x, visible.minX, visible.maxX)
       let dy = edgeSpeed(cursor.y, visible.minY, visible.maxY)
       guard dx != 0 || dy != 0 else { return }
       let newOrigin = CGPoint(x: max(0, visible.origin.x + dx), y: max(0, visible.origin.y + dy))
       scrollView.contentView.scroll(to: newOrigin)
       scrollView.reflectScrolledClipView(scrollView.contentView)
   }

